1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Derives the owner's salutation: the {@code title} followed by a single space and the last
37	     * name (e.g. {@code DR who}), or just the last name when no title is given (absent, empty or
38	     * blank).
39	     */
40	    default String salutation(Owner owner) {
41	        String lastName = owner.getLastName();
42	        String title = owner.getTitle();
43	        if (title == null || title.isBlank()) {
44	            return lastName;
45	        }
46	        return title + " " + lastName;
47	    }
48	
49	    /**
50	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
51	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
52	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
53	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
54	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
55	     * number.
56	     */
57	    default String telephoneDisplay(Owner owner) {
58	        String telephone = owner.getTelephone();
59	        if (telephone == null || telephone.isEmpty()) {
60	            return null;
61	        }
62	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
63	            return telephone;
64	        }
65	        String digits = telephone.substring(1);
66	        int countryCodeLength;
67	        if (digits.startsWith("61")) {
68	            countryCodeLength = 2;
69	        }
70	        else if (digits.startsWith("1")) {
71	            countryCodeLength = 1;
72	        }
73	        else {
74	            countryCodeLength = 1;
75	        }
76	        String countryCode = digits.substring(0, countryCodeLength);
77	        String national = digits.substring(countryCodeLength);
78	        StringBuilder grouped = new StringBuilder();
79	        for (int i = 0; i < national.length(); i++) {
80	            if (i > 0 && i % 3 == 0) {
81	                grouped.append(' ');
82	            }
83	            grouped.append(national.charAt(i));
84	        }
85	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
86	    }
87	
88	    /**
89	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
90	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
91	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
92	     * legacy records) the current date is used as the reference point.
93	     */
94	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
95	        java.time.LocalDate birthDate = owner.getBirthDate();
96	        if (birthDate == null) {
97	            return null;
98	        }
99	        java.time.LocalDate reference = owner.getRegistrationDate() != null
100	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
101	        int age = java.time.Period.between(birthDate, reference).getYears();
102	        if (age < 18) {
103	            return OwnerDto.AgeBandEnum.MINOR;
104	        }
105	        if (age < 65) {
106	            return OwnerDto.AgeBandEnum.ADULT;
107	        }
108	        return OwnerDto.AgeBandEnum.SENIOR;
109	    }
110	
111	    /**
112	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
113	     * present, otherwise {@code PHONE}.
114	     */
115	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
116	        String email = owner.getEmail();
117	        if (email != null && !email.isEmpty()) {
118	            return OwnerDto.ContactPreferenceEnum.EMAIL;
119	        }
120	        return OwnerDto.ContactPreferenceEnum.PHONE;
121	    }
122	
123	    /**
124	     * Derives the owner's locality (region) from the region-and-hash identity: it is the
125	     * {@code <REGION>} segment of the customerCode ({@code <REGION>-<HASH8>}), i.e. the region
126	     * derived from the postcode at create time. When the customerCode is absent or malformed
127	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
128	     * table, returning {@code UNKNOWN} when neither source resolves.
129	     */
130	    default String locality(Owner owner) {
131	        String code = owner.getCustomerCode();
132	        if (code != null) {
133	            int dash = code.indexOf('-');
134	            if (dash > 0) {
135	                return code.substring(0, dash);
136	            }
137	        }
138	        String region = regionFromPostcode(owner);
139	        if (region != null) {
140	            return region;
141	        }
142	        return cityRegion(owner);
143	    }
144	
145	    /**
146	     * Derives the owner's IANA timezone from the {@link #locality(Owner) locality/region}
147	     * via the fixed region-to-timezone table (NSW-&gt;Australia/Sydney,
148	     * VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Returns {@code null}
149	     * when the region is not in the table.
150	     */
151	    default String timezone(Owner owner) {
152	        String region = locality(owner);
153	        switch (region) {
154	            case "NSW":
155	                return "Australia/Sydney";
156	            case "VIC":
157	                return "Australia/Melbourne";
158	            case "QLD":
159	                return "Australia/Brisbane";
160	            default:
161	                return null;
162	        }
163	    }
164	
165	    /**
166	     * Maps the owner's city to its region via the fixed city-to-region table
167	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
168	     * when the city is absent or not in the table.
169	     */
170	    default String cityRegion(Owner owner) {
171	        String city = owner.getCity();
172	        if (city == null) {
173	            return "UNKNOWN";
174	        }
175	        switch (city) {
176	            case "Sydney":
177	                return "NSW";
178	            case "Melbourne":
179	                return "VIC";
180	            case "Brisbane":
181	                return "QLD";
182	            default:
183	                return "UNKNOWN";
184	        }
185	    }
186	
187	    /**
188	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
189	     * when the postcode is absent, malformed, or in no known range.
190	     */
191	    default String regionFromPostcode(Owner owner) {
192	        String postcode = owner.getPostcode();
193	        if (postcode == null) {
194	            return null;
195	        }
196	        int code;
197	        try {
198	            code = Integer.parseInt(postcode.trim());
199	        }
200	        catch (NumberFormatException ex) {
201	            return null;
202	        }
203	        if (code >= 2000 && code <= 2099) {
204	            return "NSW";
205	        }
206	        if (code >= 3000 && code <= 3099) {
207	            return "VIC";
208	        }
209	        if (code >= 4000 && code <= 4099) {
210	            return "QLD";
211	        }
212	        return null;
213	    }
214	
215	    /**
216	     * Returns the owner's membership points. The score starts at 0 and gains 2 when an email is
217	     * present, 1 when {@code namesakeCount} is 0, 2 when the household has 3 or more members, and 3
218	     * when tenure exceeds 365 days.
219	     */
220	    default Integer membershipPoints(Owner owner) {
221	        int points = 0;
222	        String email = owner.getEmail();
223	        if (email != null && !email.isEmpty()) {
224	            points += 2;
225	        }
226	        Integer namesakeCount = owner.getNamesakeCount();
227	        if (namesakeCount != null && namesakeCount == 0) {
228	            points += 1;
229	        }
230	        Integer householdSize = owner.getHouseholdSize();
231	        if (householdSize != null && householdSize >= 3) {
232	            points += 2;
233	        }
234	        if (tenureDays(owner) > 365) {
235	            points += 3;
236	        }
237	        return points;
238	    }
239	
240	    /**
241	     * Returns the owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
242	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or
243	     * more points.
244	     */
245	    default Integer membershipLevel(Owner owner) {
246	        int points = membershipPoints(owner);
247	        if (points <= 1) {
248	            return 1;
249	        }
250	        if (points <= 3) {
251	            return 2;
252	        }
253	        if (points <= 5) {
254	            return 3;
255	        }
256	        return 4;
257	    }
258	
259	    /**
260	     * The owner's tenure in whole days: the number of days from {@code registrationDate} to the
261	     * current date. A newly created owner (registered today) has zero tenure, and a missing
262	     * registrationDate (e.g. legacy records) is likewise treated as zero.
263	     */
264	    default long tenureDays(Owner owner) {
265	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
266	        if (registrationDate == null) {
267	            return 0;
268	        }
269	        long days = java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
270	        return Math.max(days, 0);
271	    }
272	
273	    /**
274	     * Builds the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;'
275	     * where YY is the last two digits of the registrationDate year. Returns {@code null}
276	     * when either source field is absent.
277	     */
278	    default String membershipNumber(Owner owner) {
279	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
280	            return null;
281	        }
282	        return owner.getCustomerCode() + "-M"
283	            + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
284	    }
