288	     * owner's customerCode. Non-digit characters are ignored. Returns {@code null}
289	     * when the customerCode is absent.
290	     */
291	    default Integer checkDigit(Owner owner) {
292	        String customerCode = owner.getCustomerCode();
293	        if (customerCode == null) {
294	            return null;
295	        }
296	        int sum = 0;
297	        boolean dbl = true;
298	        for (int i = customerCode.length() - 1; i >= 0; i--) {
299	            char c = customerCode.charAt(i);
300	            if (c < '0' || c > '9') {
301	                continue;
302	            }
303	            int d = c - '0';
304	            if (dbl) {
305	                d *= 2;
306	                if (d > 9) {
307	                    d -= 9;
308	                }
309	            }
310	            sum += d;
311	            dbl = !dbl;
312	        }
313	        return (10 - (sum % 10)) % 10;
314	    }
