     * when the region is not in the table.
     */
    default String timezone(Owner owner) {
        String region = locality(owner);
        switch (region) {
            case "NSW":
                return "Australia/Sydney";
            case "VIC":
                return "Australia/Melbourne";
            case "QLD":
                return "Australia/Brisbane";
            default:
